Item.method_code:
const { getState, favorites, rows, getProps, relatedTypeName } = options;
const { grid } = getState();
const { selectedRows } = grid;
const relatedId = rows.get(selectedRows[0], 'related_id');
const configId = rows.get(relatedId, 'config_id');
const { store, item } = await import('../jsBundles/store.es.js');
const isNew = item.isNew(relatedTypeName, relatedId);

if (!configId || isNew) {
	return;
}

const props = getProps();
const isAlreadyFavorited =
	favorites.filterFavorites(
		props.favorites,
		'Item',
		({ additional_data: additionalData }) => additionalData.id === configId
	).length > 0;

if (isAlreadyFavorited) {
	return;
}

const system = store.getState().system;
const { defaultLanguageCode, languages } = system;
const aliasIdentityId = system.user.identityId;

const { 'id@aras.type': contextType, keyed_name: label } = rows.get(relatedId);

const favoriteLocaleLabels =
	languages && defaultLanguageCode && languages.length > 1
		? languages.reduce((acc, { code }) => {
				if (code !== defaultLanguageCode) {
					acc[`label@aras.lang.${code}`] = label;
				}
				return acc;
			}, {})
		: {};

const newFavorite = {
	'@action': 'add',
	category: 'Item',
	contextType,
	label,
	ownedBy: aliasIdentityId,
	additional_data: { id: configId },
	quickAccessFlag: '1',
	...favoriteLocaleLabels
};

return aras.getMainWindow().ArasCore.Dialogs.openFavoriteDialog(newFavorite);
